/**
 * generated by stackra gen from stackra.config.ts (targets, render), src/config/telemetry.config.ts
 * (bundle budgets), the class components under src/, vite.extend.ts and runway.yaml (environments.dev: port, host;
 * environments.<env>.vars; telemetry.sentryProject) — do not edit
 * Purpose: the Vite config of the web target rendered on the Worker (`RenderMode.Server`), with
 *          `entry/worker.ts` as the Worker entry. `@stackra/vite-plugin` bundles the Cloudflare
 *          Workers runtime for the `ssr` environment, Tailwind v4, React Router framework mode, the
 *          `#stackra/*` virtual modules with HMR, `classComponents()` from `@stackra/gen/vite` (it
 *          compiles every `extends Component` class to a function component before the React
 *          Compiler runs, with source maps back to the class), the `.server.ts` browser-import
 *          refusal, hidden sourcemaps uploaded to Sentry, the `safari17` client target and the
 *          bundle budgets as a failing check. Nothing is inlined as a `data:` URL or an inline
 *          script, so the CSP needs no `unsafe-inline` and no `data:` source.
 * Boundary: the dev server block is the member runway's through `.stackra/dev/ports.json`. The
 *           member-root `vite.extend.ts` is merged last with `mergeConfig`, after the stackra
 *           plugin, and may only add plugin instances (gen fails when it changes an owned key); it
 *           is the only hatch, and the gitignored `vite.config.ts` at the member root re-exports
 *           this file.
 * Runtime: node
 */
import { defineConfig, mergeConfig } from "vite";
import { classComponents } from "@stackra/gen/vite";
import { stackra } from "@stackra/vite-plugin";
import { definesFor, devServer } from "@stackra/runway/vite";
import app from "../stackra.config";
import extend from "../vite.extend";

export default defineConfig((env) =>
  mergeConfig(
    stackra.viteConfig(app, {
      mode: env.mode,
      // Target.Web with RenderMode.Server: cloudflare, tailwindcss, reactRouter, stackra
      target: app.targets[0],
      render: app.render,
      server: devServer("web"), // runway.yaml environments.dev via ports.json
      define: definesFor("web", process.env.STACKRA_ENVIRONMENT ?? "dev"), // public fields only
      budgets: { entryKb: 200, routeKb: 100 }, // telemetry.config.ts bundle; gzipped
      // hidden: maps are uploaded to Sentry and never served; 0: no asset becomes a data: URL
      build: { target: "safari17", sourcemap: "hidden", assetsInlineLimit: 0 },
      // runway.yaml telemetry.sentryProject; the upload token is the release job's, never here
      sourcemaps: { upload: "sentry", project: "acme-web" },
      buildTime: true, // defines __BUILD_TIME__: lastmod of the marketing sitemap entries
      // first, so React Router, the React Compiler and Fast Refresh see plain function components
      plugins: [classComponents()],
    }),
    extend(env),
  ),
);
